-- Reviewed Bloodforged drop catalogue; each row must match item_template at server start.
CREATE TABLE IF NOT EXISTS `coa_bloodforged_catalogue` (
  `entry` INT UNSIGNED NOT NULL,
  `quality` TINYINT UNSIGNED NOT NULL,
  `required_level` TINYINT UNSIGNED NOT NULL,
  `item_level` SMALLINT UNSIGNED NOT NULL,
  PRIMARY KEY (`entry`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
TRUNCATE TABLE `coa_bloodforged_catalogue`;
